-- session session source/persistence/compression utilities
-- Generated by merging focused helpers into an agent-discoverable module.

local history_core = require("maxa.session.history_core")
local compaction_messages = require("maxa.session.compaction_messages")

local M = {}

M.read_chat = history_core.read_chat
M.generate_save_id = history_core.generate_save_id
M.get_protected_prefix_count = compaction_messages.get_protected_prefix_count
M.set_protected_prefix_count = compaction_messages.set_protected_prefix_count
M.strip_runtime_control_messages = compaction_messages.strip_runtime_control_messages
M.strip_token_warning_messages = compaction_messages.strip_token_warning_messages
M.COMPRESS_MODE = compaction_messages.COMPRESS_MODE
M.PROTECTED_PREFIX_FIELD = compaction_messages.PROTECTED_PREFIX_FIELD

-- ============================================================
-- Source: utils/session_source.lua
-- ============================================================

local TOKEN_WARNING_STATE_KEY = "session_admin_token_warning"

function M.get_messages_source(save_id, caller)
  if not save_id or save_id == "" then
    -- 从当前会话获取
    if not caller or not caller.maxa_ai then
      return nil, "No current session found (must be called from a Maxa AI chat or provide save_id)"
    end

    local chat = caller.maxa_ai.chat
    if not chat or not chat.messages then
      return nil, "Current session has no messages"
    end

    return {
      messages = M.strip_runtime_control_messages(M.strip_token_warning_messages(chat.messages)),
      source_type = "current",
      save_id = chat.opts and chat.opts.save_id or nil,
      chat = chat,
      chat_data = nil,
    },
      nil
  else
    -- 从保存的会话文件读取
    local chat_data, err = M.read_chat(save_id)
    if not chat_data then
      return nil, "Failed to read chat - " .. (err or "unknown error")
    end
    -- 检查是否为当前会话（如果 caller 存在）
    local chat = nil
    if caller and caller.maxa_ai then
      local current_chat = caller.maxa_ai.chat
      if current_chat and current_chat.opts and current_chat.opts.save_id == save_id then
        chat = current_chat
      end
    end

    return {
      messages = M.strip_runtime_control_messages(M.strip_token_warning_messages(chat_data.messages or {})),
      source_type = chat and "current" or "saved",
      save_id = save_id,
      chat = chat,
      chat_data = chat_data,
    },
      nil
  end
end

--- 获取 adapter 对象
---@param adapter_name string adapter 名称
---@return table|nil adapter 对象
function M.resolve_adapter(adapter_name)
  local adapter = require("maxa.adapters").resolve(adapter_name)
  if not adapter or adapter.type ~= "http" then
    return nil
  end
  adapter:map_schema_to_params(require("maxa.schema").get_default(adapter))
  return adapter
end

--- 获取 history extension API
---@return table|nil api history extension API
function M.get_history_api()
  local ok, session = pcall(require, "maxa.session")
  return ok and session.history() or nil
end

--- 保存消息到历史文件
---@param messages table[] 消息列表
---@param save_id string 会话 ID
---@param chat_data table|nil 原始会话数据（用于继承设置）
---@param adapter_name string|nil adapter 名称
---@return boolean success
---@return string|nil error
function M.save_messages_to_history(messages, save_id, chat_data, adapter_name)
  messages = M.strip_runtime_control_messages(M.strip_token_warning_messages(messages or {}))

  local history_api = M.get_history_api()
  if not history_api or not history_api.save_chat then
    return false, "Failed to get history API"
  end

  chat_data = chat_data or {}
  local meta = vim.deepcopy(chat_data._meta or {})
  meta[TOKEN_WARNING_STATE_KEY] = nil
  adapter_name = adapter_name or chat_data.adapter or "anthropic"

  local chat_obj = {
    opts = {
      save_id = save_id,
      title = chat_data.title,
      cwd = chat_data.cwd,
    },
    messages = messages,
    settings = chat_data.settings or {},
    _meta = meta,
    adapter = { name = adapter_name },
    context_items = chat_data.context_items or {},
    tool_registry = {
      schemas = chat_data.schemas or {},
      in_use = chat_data.in_use or {},
    },
    cycle = (chat_data.cycle or 1) + 1,
  }

  local protected_count = M.get_protected_prefix_count(chat_data)
  chat_obj._compact_protected_prefix_count = protected_count
  chat_obj.opts[M.PROTECTED_PREFIX_FIELD] = protected_count

  history_api.save_chat(chat_obj)
  return true, nil
end

--- 同步修正已保存会话的 adapter/settings 元数据，确保压缩执行模型不会污染业务会话。
---@param history_api table
---@param save_id string
---@param session_state table|nil {adapter_name?, model_name?, temperature?, settings?}
---@return boolean success
---@return string|nil error
function M.sync_saved_chat_session_state(history_api, save_id, session_state)
  if not session_state or not save_id then
    return true, nil
  end

  if type(history_api) ~= "table" or type(history_api.load_chat) ~= "function" then
    return false, "history API missing load_chat"
  end

  local chat_data = history_api.load_chat(save_id)
  if not chat_data then
    return false, "Failed to load compressed chat metadata: " .. save_id
  end

  local protected_prefix_count = M.get_protected_prefix_count(chat_data)

  if session_state.adapter_name and session_state.adapter_name ~= "" then
    chat_data.adapter = session_state.adapter_name
  end

  chat_data.settings = vim.deepcopy(session_state.settings or chat_data.settings or {})
  if session_state.model_name and session_state.model_name ~= "" then
    chat_data.settings.model = session_state.model_name
  end
  if session_state.temperature ~= nil then
    chat_data.settings.temperature = session_state.temperature
  end

  -- 优先使用公开 API；其 save_chat 期望的是 chat 对象而不是裸 chat_data。
  if type(history_api.save_chat) == "function" then
    local chat_obj = {
      opts = {
        save_id = chat_data.save_id,
        title = chat_data.title,
        cwd = chat_data.cwd,
        title_refresh_count = chat_data.title_refresh_count or 0,
        compact_protected_prefix_count = protected_prefix_count,
      },
      _compact_protected_prefix_count = protected_prefix_count,
      _meta = vim.deepcopy(chat_data._meta or {}),
      messages = M.strip_runtime_control_messages(M.strip_token_warning_messages(chat_data.messages or {})),
      settings = vim.deepcopy(chat_data.settings or {}),
      adapter = {
        name = chat_data.adapter or session_state.adapter_name or "unknown",
      },
      context_items = chat_data.context_items or {},
      tool_registry = {
        schemas = chat_data.schemas or {},
        in_use = chat_data.in_use or {},
      },
      cycle = chat_data.cycle or 1,
    }

    if chat_obj.settings and chat_obj.settings.model then
      chat_obj.adapter.model = { name = chat_obj.settings.model }
    end

    chat_obj._meta[TOKEN_WARNING_STATE_KEY] = nil
    local ok_save, save_err = pcall(history_api.save_chat, chat_obj)
    if not ok_save then
      return false, save_err or "Failed to rewrite compressed chat metadata"
    end
    return true, nil
  end

  if type(history_api._save_chat_to_file) == "function" then
    chat_data.messages = M.strip_runtime_control_messages(M.strip_token_warning_messages(chat_data.messages or {}))
    chat_data._meta = vim.deepcopy(chat_data._meta or {})
    chat_data._meta[TOKEN_WARNING_STATE_KEY] = nil
    local save_result = history_api._save_chat_to_file(chat_data)
    if save_result and save_result.ok == false then
      return false, save_result.error or "Failed to rewrite compressed chat metadata"
    end

    if type(history_api._update_index_entry) == "function" then
      local index_result = history_api._update_index_entry(chat_data)
      if index_result and index_result.ok == false then
        return false, index_result.error or "Failed to update compressed chat index metadata"
      end
    end

    return true, nil
  end

  -- 兼容最小 exports：无持久化入口时不阻断压缩主流程，只提示 metadata 未同步。
  return true, "history API missing save_chat and private storage methods; metadata sync skipped"
end

--- 创建新会话（从消息列表）
---@param messages table[] 消息列表
---@param parent_chat table|nil 父会话对象（用于继承设置）
---@param on_created function|nil 创建成功后的回调

-- ============================================================
-- Source: utils/session_create.lua
-- ============================================================

local TOKEN_WARNING_STATE_KEY = "session_admin_token_warning"

function M.create_new_session_from_messages(messages, parent_chat, on_created)
  local Chat = require("maxa.interactions.chat")

  -- 保存父会话的状态
  local parent_bufnr = parent_chat and parent_chat.bufnr or vim.api.nvim_get_current_buf()
  local parent_settings = parent_chat and parent_chat.settings and vim.deepcopy(parent_chat.settings) or nil
  local parent_adapter = parent_chat and parent_chat.adapter or nil
  local parent_tool_registry = parent_chat and parent_chat.tool_registry or nil
  local parent_cycle = (parent_chat and parent_chat.cycle or 1) + 1

  local buffer_context = (parent_chat and parent_chat.buffer_context)
    or require("maxa.utils.context").get(parent_bufnr)

  -- 关闭当前会话
  if parent_chat then
    if parent_chat.close then
      parent_chat:close()
    elseif parent_chat.bufnr and vim.api.nvim_buf_is_valid(parent_chat.bufnr) then
      vim.api.nvim_buf_delete(parent_chat.bufnr, { force = true })
    end
  end

  -- 创建新会话
  local parent_protected_count = M.get_protected_prefix_count(parent_chat)
  local ok, new_chat = pcall(Chat.new, {
    adapter = parent_adapter,
    buffer_context = buffer_context,
    cwd = (parent_chat and parent_chat.opts and parent_chat.opts.cwd) or buffer_context.cwd,
    project_root = (parent_chat and parent_chat.opts and parent_chat.opts.project_root) or buffer_context.project_root,
    messages = messages,
    settings = parent_settings,
    auto_submit = false,
    compact_protected_prefix_count = parent_protected_count,
  })

  if ok and new_chat then
    -- 继承 tool_registry（工具 schemas 每次 API 请求都需要发送，必须保留）
    -- 注意：不继承 context_items，因为上下文内容已在 messages 中以 OK_TAGS 消息形式保留
    if parent_tool_registry then
      require("maxa.session.builtin_registry").apply(
        new_chat,
        parent_tool_registry.schemas,
        parent_tool_registry.in_use
      )
    end

    -- 继承 cycle 计数
    new_chat.cycle = parent_cycle
    -- 压缩产物只能继承已有 protected prefix，不能因“新会话已有 messages”而扩大保护区。
    M.set_protected_prefix_count(new_chat, parent_protected_count)
    if parent_chat and parent_chat._meta then
      new_chat._meta = vim.deepcopy(parent_chat._meta)
    end

    if on_created then
      on_created(new_chat)
    end

    return true
  else
    vim.notify(string.format("[session] Failed to create new session: %s", tostring(new_chat)), vim.log.levels.ERROR)
    return false
  end
end

-- ============================================================
-- Source: utils/compression_result.lua
-- ============================================================


--- 应用压缩结果（根据 mode 处理）
---@param params table 参数
---  - messages: table[] 压缩后的消息
---  - mode: string "auto" | "overwrite" | "new"
---  - source: table get_messages_source 的返回值
---  - adapter_name: string|nil adapter 名称
---  - on_new_session: function|nil 新会话创建后的回调
---@return table result {action, save_id}
---@return string|nil error
function M.apply_compression_result(params)
  local messages = M.strip_token_warning_messages(params.messages)
  local mode = params.mode or M.COMPRESS_MODE.AUTO
  local source = params.source
  local adapter_name = params.adapter_name
  local on_new_session = params.on_new_session

  local is_current = source.source_type == "current"
  local chat = source.chat
  local save_id = source.save_id
  local chat_data = source.chat_data

  local protected_count = M.get_protected_prefix_count(source)


  -- 确定实际操作
  local action
  if mode == M.COMPRESS_MODE.AUTO then
    action = is_current and "new" or "overwrite"
  else
    action = mode
  end

  if action == "overwrite" then
    -- 覆盖模式：保存到历史文件
    if is_current and chat then
      -- 当前会话：直接替换 messages 并保存
      chat.messages = messages
      M.set_protected_prefix_count(chat, protected_count)
      -- 触发保存（如果有 save_id）
      if save_id then
        chat_data = chat_data or {}
        chat_data[M.PROTECTED_PREFIX_FIELD] = protected_count
        chat_data.opts = chat_data.opts or {}
        chat_data.opts[M.PROTECTED_PREFIX_FIELD] = protected_count
        local ok, err = M.save_messages_to_history(messages, save_id, chat_data, adapter_name)
        if not ok then
          return nil, err
        end
      end
      return { action = "overwrite", save_id = save_id }, nil
    else
      -- 历史会话：直接保存
      chat_data = chat_data or {}
      chat_data[M.PROTECTED_PREFIX_FIELD] = protected_count
      chat_data.opts = chat_data.opts or {}
      chat_data.opts[M.PROTECTED_PREFIX_FIELD] = protected_count
      local ok, err = M.save_messages_to_history(messages, save_id, chat_data, adapter_name)
      if not ok then
        return nil, err
      end
      return { action = "overwrite", save_id = save_id }, nil
    end
  elseif action == "new" then
    -- 新建模式
    if is_current and chat then
      -- 当前会话：阻止 auto_submit，通过回调创建新会话。
      if chat.tools then
        chat.tools.status = "compact_done"
      end

      local callback_registered = false
      if chat.add_callback then
        chat:add_callback("on_completed", function()
          if not callback_registered then
            callback_registered = true
            vim.schedule(function()
              M.create_new_session_from_messages(messages, chat, on_new_session)
            end)
          end
        end)
      else
        vim.defer_fn(function()
          M.create_new_session_from_messages(messages, chat, on_new_session)
        end, 1000)
      end

      return { action = "new", save_id = nil, pending = true }, nil
    else
      -- 历史会话：生成新 save_id，保存，更新索引
      local new_save_id = M.generate_save_id({ prefix = "compact" })
      chat_data = chat_data or {}
      chat_data[M.PROTECTED_PREFIX_FIELD] = protected_count
      chat_data.opts = chat_data.opts or {}
      chat_data.opts[M.PROTECTED_PREFIX_FIELD] = protected_count
      local ok, err = M.save_messages_to_history(messages, new_save_id, chat_data, adapter_name)
      if not ok then
        return nil, err
      end
      return { action = "new", save_id = new_save_id, original_save_id = save_id }, nil
    end
  end

  return nil, "Unknown mode: " .. tostring(mode)
end

return M
